// Step 1: Create a Set object with 5 unique elements
let mySet = new Set([1, "apple", true, { key: 'value' }, new Set(['first', 'second'])]);

// Step 2: Write a function that prints the type of each element
function printTypes(set) {
  for (let elem of set) {
    console.log(`The type of ${elem} is ${typeof elem}`);
  }
}

// Step 3: Create a method that checks if a passed element exists in the Set and returns a Boolean value
function checkIfExists(set, elem) {
  // Handle case where elem is also a Set
  if (elem instanceof Set) {
    return elem.every(item => set.has(item));
  }
  // Generic case
  return set.has(elem);
}

// Test the method
console.log(checkIfExists(mySet, "apple")); // true
console.log(checkIfExists(mySet, "banana")); // false
console.log(checkIfExists(mySet, mySet)); // true
```
